CommonData.BannerCustomCSS:
#onetrust-pc-sdk {
  max-width: 600px !important;
  border-radius: 8px !important;

  *:focus {
    outline: none !important;
  }

  .ot-pc-logo {
    display: none;
  }

  .ot-pc-header {
    display: flex;
    align-items: center;
    justify-content: start;

    &::after {
      /* Generic + GDPR ONLY; For US+CA override, see bottom of the styles */
      content: 'Privacy Preference Center';
      font-weight: bold;
    }

    #close-pc-btn-handler {
      margin: -2px 5px 0 0 !important;
      transform: scale(1.5);
    }
  }

  #ot-pc-title {
    display: none;
  }

  #ot-pc-desc {
    margin-top: 16px;

    .privacy-notice-link, .ot-text-link {
      color: #1E39D2;
      text-decoration: none;
    }

    br {
      display: none;
    }
  }

  .ot-subgrp {
    padding: 0 !important;
    margin: 0 !important;
  }

  #accept-recommended-btn-handler {
    padding: 9px 16px !important;
    border-radius: 6px !important;
    background: #1E39D2 !important;
  }

  .ot-accordion-layout {
    border: none !important;
  }

  .ot-accordion-layout.ot-cat-item:first-of-type .ot-acc-hdr {
    border-top-left-radius: 8px !important;
    border-top-right-radius: 8px !important;
  }

  .ot-accordion-layout.ot-cat-item:last-of-type .ot-acc-hdr {
    border-bottom-left-radius: 8px !important;
    border-bottom-right-radius: 8px !important;
  }

  .ot-plus-minus>span {
    background-color: #696969 !important;
  }

  .ot-always-active {
    color: #696969 !important;
    margin-right: 15px !important;
  }

  .ot-acc-hdr {
    background-color: #F5F5F5;
  }

  .ot-cat-header {
    min-height: 0 !important;
  }

  .ot-switch {
    height: 18px !important;
    width: 35px !important;
  }

  .ot-switch-nob::before {
    height: 10px !important;
    width: 10px !important;
    bottom: 3px !important;
  }

  .ot-tgl {
    margin-right: 15px !important;
  }

  .ot-tgl input:checked+.ot-switch .ot-switch-nob:before {
    transform: translateX(17px) !important;
  }

  .ot-tgl input:focus+.ot-switch {
    outline: none !important;
    outline-width: 0 !important;
  }

  input[type="checkbox"]:checked+label>span {
    background-color: #1E39D2 !important;
  }

  .ot-acc-txt {
    background-color: #ffffff !important;
    border-left: 1px solid #f5f5f5;
    border-right: 1px solid #f5f5f5;
    border-bottom: 1px solid #f5f5f5;
  }

  .ot-pc-footer-logo {
    display: none;
  }

  .ot-btn-container {
    button {
      border-radius: 6px !important;
      padding: 9px 16px !important;
      margin-top: 20px !important;
      margin-bottom: 20px !important;
    }

    .ot-pc-refuse-all-handler {
      border: 1px solid #1E39D2 !important;
      color: #1E39D2 !important;
      background: transparent !important;
      margin-right: 4px !important;
    }

    .save-preference-btn-handler {
      background: #1E39D2 !important;
    }
  }

  #ot-pc-content {
    bottom: 73px !important;
    padding-bottom: 12px !important;
  }

  @media only screen and (max-width: 476px) {
    .ot-btn-container {
      padding: 8px 0 !important;
      text-align: right;
      margin: 1px 3px 0 10px;
      width: calc(100% - 23px);

      .save-preference-btn-handler{
        margin-right: 0;
      }

      button {
        margin-top: 8px !important;
        margin-bottom: 8px !important;
        width: auto !important;
      }
    }

    #accept-recommended-btn-handler {
      width: auto !important;
    }

    #ot-pc-content {
      bottom: 113px !important;
    }
  }

  @media only screen and (max-width: 600px) {
    top: 16px !important;
    left: 16px !important;
    right: 16px !important;
    width: calc(100% - 32px) !important;
    height: calc(100% - 32px) !important;
    min-width: 0 !important;
  }
}

#onetrust-banner-sdk:focus {
  outline: none;
}

#onetrust-banner-sdk {
  max-width: 420px !important;
  border-radius: 8px !important;
  padding: 24px !important;

  *:focus {
    outline: none !important;
  }

  @media only screen and (max-width: 600px) {
    transform: translateY(1rem);
  }

  #onetrust-button-group-parent {
    padding: 0 !important;
  }

  #onetrust-policy-title {
    padding-left: 0 !important;
  }

  #onetrust-policy-text {
    padding-left: 0 !important;
    padding-right: 0 !important;
    padding-bottom: 24px !important;
  }

  #onetrust-policy {
    margin-top: 0;
  }

  #onetrust-button-group {
    display: flex;
    flex-direction: column-reverse;
    gap: 12px;

    #onetrust-pc-btn-handler {
      width: 100%;
      max-width: 100%;
      margin: 0 !important;
      background-color: #ffffff;
      color: #1E39D2;
      border-color: #1E39D2;
    }

    .onetrust-banner-options {
      display: flex;
      flex-direction: column-reverse;
      max-width: 100%;
      gap: 12px;
      margin: 0 !important
    }

    #onetrust-reject-all-handler,
    #onetrust-accept-btn-handler {
      flex: 1;
      margin-bottom: 0;
      background: #1E39D2;
      margin: 0 !important;
    }

    button {
      border-radius: 6px !important;
      padding: 9px 16px !important;
    }
  }

  #ot-sdk-btn {
    background-color: transparent !important;
  }

  .ot-text-link {
    color: #1E39D2 !important;
    text-decoration: none !important;
    margin: 0 !important;
    font-weight: bold !important;
  }

  @media only screen and (max-width: 600px) {  
    transform: translateY(0rem) !important;

    .ot-btn-container {
      padding-bottom: 16px !important;
    }
      button {
        margin-top: 16px !important;
        margin-bottom: 0 !important;
      }
    }

  @media only screen and (max-width: 450px) {
    transform: translateY(0rem) !important;
    left: 0 !important;
    bottom: 0 !important;
    right: 0 !important;
    width: 100% !important;
    max-width: none !important;
  }
}
/* Remove background color from footer link */
#ot-sdk-btn {
  background-color: transparent !important;
}

/* US+CA ONLY Below */
#onetrust-pc-sdk {
  .ot-pc-header {
    &::after {
      content: 'Do Not Sell or Share My Personal Data';
    }
  }

  #ot-pc-content {
    bottom: 73px !important;
  }
}

#onetrust-banner-sdk {
  #onetrust-button-group {
    gap: 12px;

    @media only screen and (min-width: 400px) {
      display: flex;
      flex-direction: row;
      justify-content: flex-end;
      width: 100%;

      #onetrust-pc-btn-handler {
        width: auto;
        max-width: none;
      }
    }

    #onetrust-pc-btn-handler {
      background-color: #ffffff;
      color: #1E39D2;
      border-color: #1E39D2;
    }

    #onetrust-reject-all-handler,
    #onetrust-accept-btn-handler {
      flex: 1;
      background: #1E39D2;
    }
  }
}
